library(creditratingsystem)
target<-list(event='default',probability_measure='PHYSICAL',default_definition='90DPD',unit='obligor',horizon_days=30,default_grade='D')
sample_data<-function(p=c(.1,.2,.7,.8),coverage=TRUE){
 predictions<-lapply(seq_along(p),function(j){i<-j-1L;list(forecast_id=paste0('f',i),case_id=paste0('c',i),entity_id=paste0('e',i),cluster_id=paste0('u',i),cohort='2025-01',segment='retail',model_id='m',model_version='1',forecast_at='2025-01-01',known_at='2025-01-01',pd=p[j],target=target,origin_grade='A',decision=if(p[j]<.5)'approve' else 'decline',override=FALSE,prediction_origin='OUT_OF_TIME')})
 events<-lapply(which((seq_along(p)-1L)%%2==1),function(j)list(event_id=paste0('d',j-1L),entity_id=paste0('e',j-1L),event_at='2025-01-10',known_at='2025-01-11',event='default',default_definition='90DPD'))
 cover<-if(coverage)lapply(seq_along(p),function(j)list(entity_id=paste0('e',j-1L),complete_through='2025-01-31',known_at='2025-02-01')) else list()
 list(predictions=predictions,outcome_events=events,coverage=cover)
}
cohort<-function(p=c(.1,.2,.7,.8),cutoff='2025-02-15',coverage=TRUE)do.call(build_monitoring_cohorts,c(sample_data(p,coverage),list(target_contract=target,evaluation_cutoff=cutoff)))
expect_code<-function(expr,code){actual<-tryCatch({force(expr);'NO_ERROR'},creditratingsystem_error=function(e)e$code);stopifnot(identical(actual,code))}
ci<-cohort(cutoff='2025-01-20');stopifnot(is.null(ci$value$rows[[1]]$target),ci$value$rows[[2]]$target==1,!any(vapply(ci$value$rows,`[[`,logical(1),'eligible')))
cn<-cohort(coverage=FALSE);stopifnot(cn$value$rows[[1]]$status=='MISSING_OUTCOME',cn$value$rows[[2]]$eligible)
s<-sample_data();s$predictions[[1]]$outcome_grade<-'LEAKED';s$outcome_events<-c(s$outcome_events,list(list(event_id='rating',entity_id='e0',event_at='2025-01-15',known_at='2025-01-16',event='rating',grade='B',default_definition='90DPD'),list(event_id='future',entity_id='e0',event_at='2025-01-20',known_at='2025-03-01',event='rating',grade='C',default_definition='90DPD'),list(event_id='exit',entity_id='e2',event_at='2025-01-15',known_at='2025-01-16',event='exit',default_definition='90DPD')))
cb<-do.call(build_monitoring_cohorts,c(s,list(target_contract=target,evaluation_cutoff='2025-02-15')));stopifnot(cb$value$rows[[1]]$outcome_grade=='B',cb$value$rows[[2]]$outcome_grade=='D',cb$value$rows[[3]]$status=='CENSORED',cb$diagnostics$ignored_not_yet_known_records==1)
ref<-list(start='2025-01-01',end='2025-01-31');b<-cohort();m<-monitor_rating_cohort(b,c('cohort','model_version'),ref,5,'iid_homogeneous_binomial')$value[[1]];stopifnot(m$metrics$auc==.75,abs(m$metrics$brier-(.01+.64+.49+.04)/4)<1e-14,m$status=='INSUFFICIENT_INFORMATION')
s<-sample_data();s$outcome_events<-list();zero<-do.call(build_monitoring_cohorts,c(s,list(target_contract=target,evaluation_cutoff='2025-02-15')));m<-monitor_rating_cohort(zero,'cohort',ref,1,'iid_homogeneous_binomial')$value[[1]];stopifnot(is.null(m$metrics$auc),abs(m$intervals$observed_rate$upper-(1-.025^.25))<1e-14)
s<-sample_data();s$predictions[[2]]$cluster_id<-'u0';repeated<-do.call(build_monitoring_cohorts,c(s,list(target_contract=target,evaluation_cutoff='2025-02-15')));expect_code(monitor_rating_cohort(repeated,'cohort',ref,1,'iid_homogeneous_binomial'),'INCOMPATIBLE_ASSUMPTIONS')
all_perm<-function(x){if(length(x)==1)return(matrix(x,nrow=1));do.call(rbind,lapply(seq_along(x),function(i)cbind(x[i],all_perm(x[-i]))))};perms<-all_perm(0:3)
for(method in c('ks','wasserstein')){v<-detect_credit_feature_drift(list(list(x=0),list(x=1)),list(list(x=2),list(x=3)),'x',method,perms,'holm','exchangeable_rows')$value[[1]];stopifnot(abs(v$statistic-if(method=='ks')1 else 2)<1e-14,abs(v$p_value-9/25)<1e-14)}
v<-detect_credit_feature_drift(list(list(x=0)),list(list(x=2)),'x','mmd_rbf',rbind(c(0,1),c(1,0)),'none','exchangeable_rows',bandwidth=1)$value[[1]];stopifnot(abs(v$statistic-2*(1-exp(-2)))<1e-14,v$p_value==1)
v<-detect_credit_feature_drift(list(list(x='a'),list(x='b')),list(list(x='c'),list(x=NULL)),'x','psi',NULL,'not_applicable','descriptive',frozen_bins=list(x=list(kind='categorical',levels=list('a','b'))))$value[[1]];stopifnot(abs(v$statistic-log(3))<1e-14,v$new_category_rows==1,v$current_missing==1,is.null(v$p_value))
expect_code(detect_credit_feature_drift(list(list(x=0),list(x=1)),list(list(x=2),list(x=3)),'x','ks',rbind(0:3,c(0,2,1,3)),'none','exchangeable_clusters',permutation_units=c('a','a','b','b')),'INVALID_PERMUTATIONS')
residuals<-lapply(1:3,function(i)list(time=paste0('2025-02-0',i),value=1,mature=TRUE));ns<-list(model_id='m',model_version='1',calibration_id='pretest',residual_scale='observed_minus_expected_rate',dependence='prespecified_dependent',probability_measure='PHYSICAL',calibrated_before='2025-01-31',validation_paths_independent=TRUE)
e<-detect_pd_calibration_drift(residuals,'ewma',list(smoothing=.5),matrix(0,19,3),ns,.05,matrix(0,20,3));stopifnot(max(abs(unlist(e$value$statistic_path)-c(.5,.75,.875)))<1e-14,e$value$threshold==0,e$value$first_crossing_index==0,abs(e$value$validation_false_alarm$interval$upper-(1-.025^(1/20)))<1e-14)
v<-detect_pd_calibration_drift(residuals,'cusum',list(allowance=.2),matrix(0,19,3),ns,.05);stopifnot(max(abs(unlist(v$value$statistic_path)-c(.8,1.6,2.4)))<1e-14,v$diagnostics$order_statistic_rank==19)
draws<-list(paste0('u',0:3),paste0('u',3:0),rep('u0',4),rep('u3',4));protocol<-list(evaluation_role='OUT_OF_TIME_TEST',multiple_challenger_policy='single_prespecified',protocol_id='holdout-v1')
v<-compare_challenger_cohorts(b,b,draws,protocol)$value;stopifnot(all(unlist(v$differences)==0),v$intervals$brier$degenerate,v$intervals$auc$identified_resamples==2)
v<-compare_challenger_cohorts(b,cohort(c(.49,.5,.51,.52)),draws,protocol)$value;stopifnot(v$differences$auc==0,v$differences$brier<0,v$recommendation=='REQUIRES_MULTIDIMENSIONAL_REVIEW')
v<-compare_challenger_cohorts(b,cn,list(c('u1','u3'),c('u1','u1')),protocol)$value;stopifnot(identical(unlist(v$eligibility_disagreements),c('c0','c2')),v$paired_count==2)
labels<-lapply(0:3,function(i)list(case_id=paste0('c',i),group=if(i<2)'A' else 'B'));v<-diagnose_fairness_slices(b,labels,'A','documented approved analysis',3,.5,draws)$value
stopifnot(v[[1]]$metrics$selection_rate==1,v[[2]]$metrics$selection_rate==0,v[[1]]$metrics$true_positive_rate==0,v[[2]]$metrics$true_positive_rate==1,v[[2]]$reference_gaps$false_positive_rate==1,v[[1]]$status=='INSUFFICIENT_INFORMATION')
v<-diagnose_fairness_slices(ci,labels,'A','approved',1,.5,draws)$value;stopifnot(v[[1]]$metrics$selection_rate==1,is.null(v[[1]]$metrics$true_positive_rate),v[[1]]$mature_observed_count==0)
ns2<-list(model_id='m',model_version='1',calibration_id='v',residual_scale='rate',dependence='independent',probability_measure='PHYSICAL',calibrated_before='2025-01-01');res2<-list(list(time='2025-02-01',value=9,mature=TRUE))
v<-detect_pd_calibration_drift(res2,'cusum',list(allowance=0),matrix(0:8,ncol=1),ns2,.2);stopifnot(v$value$threshold==7,v$diagnostics$order_statistic_rank==8)
expect_code(detect_pd_calibration_drift(res2,'cusum',list(allowance=0),matrix(0,2,1),ns2,.05),'INSUFFICIENT_NULL_SIMULATIONS')
res2[[1]]$mature<-FALSE;expect_code(detect_pd_calibration_drift(res2,'cusum',list(allowance=0),matrix(0,19,1),ns2,.05),'INVALID_RESIDUALS')
